default.shell:
$mismatchCount = 0

$key = Get-Item -LiteralPath 'HKLM:\Software\Policies\Microsoft\Windows\Eventlog\Security' -ErrorAction SilentlyContinue
$current = $null
if ($key) { $current = $key.GetValue('MaxSize', $null, 'DoNotExpandEnvironmentNames') }
if (-not ($current -is [int] -and [BitConverter]::ToUInt32([BitConverter]::GetBytes($current), 0) -eq [uint32]$ODV_security_max_log_file_size)) {
    Write-Output 'Mismatch: HKLM:\Software\Policies\Microsoft\Windows\Eventlog\Security [MaxSize]'
    $mismatchCount++
}

if ($mismatchCount -gt 0) { exit 1 }
exit 0

steps.shell:
$ErrorActionPreference = 'Stop'
trap { Write-Output $_.Exception.Message; exit 1 }

if (-not (Test-Path -LiteralPath 'HKLM:\Software\Policies\Microsoft\Windows\Eventlog\Security')) {
    New-Item -Path 'HKLM:\Software\Policies\Microsoft\Windows\Eventlog\Security' -Force | Out-Null
}
New-ItemProperty -LiteralPath 'HKLM:\Software\Policies\Microsoft\Windows\Eventlog\Security' -Name 'MaxSize' -Value $ODV_security_max_log_file_size -PropertyType DWord -Force | Out-Null
exit 0
